/* Generated by Simple RGB LED Tool. */
#include "llsi_led_pattern_player.h"

static const llsi_led_pattern_frame_t g_rgb_pattern[G_RGB_PATTERN_FRAME_COUNT] =
{
    { 100u, {
        { 0xFFu, 0x00u, 0x00u },
        { 0x00u, 0xFFu, 0x00u },
        { 0x00u, 0x00u, 0xFFu },
        { 0x00u, 0x00u, 0x00u }
    } },
    { 100u, {
        { 0x00u, 0x00u, 0x00u },
        { 0xFFu, 0x00u, 0x00u },
        { 0x00u, 0xFFu, 0x00u },
        { 0x00u, 0x00u, 0xFFu }
    } }
};

void g_rgb_pattern_render_frame(const llsi_led_pattern_frame_t *frame)
{
    uint8_t i;

    if (frame == 0)
    {
        return;
    }
    LLSI_LED_PATTERN_DRV_Clear();
    for (i = 0u; i < G_RGB_PATTERN_LED_COUNT; i++)
    {
        LLSI_LED_PATTERN_DRV_SetPixel(i, frame->led[i].r, frame->led[i].g, frame->led[i].b);
    }
    LLSI_LED_PATTERN_DRV_Show();
}

void g_rgb_pattern_play_once(void)
{
    uint16_t frame_index;

    for (frame_index = 0u; frame_index < G_RGB_PATTERN_FRAME_COUNT; frame_index++)
    {
        g_rgb_pattern_render_frame(&g_rgb_pattern[frame_index]);
        LLSI_LED_PATTERN_DRV_DelayMs(g_rgb_pattern[frame_index].duration_ms);
    }
}

uint16_t g_rgb_pattern_step(uint16_t frame_index)
{
    uint16_t next;

    if (frame_index >= G_RGB_PATTERN_FRAME_COUNT)
    {
        frame_index = 0u;
    }
    g_rgb_pattern_render_frame(&g_rgb_pattern[frame_index]);
    next = (uint16_t)(frame_index + 1u);
    if (next >= G_RGB_PATTERN_FRAME_COUNT)
    {
        next = 0u;
    }
    return next;
}
